import sys

MOD = 10**9 + 7

def modinv(a, m):
    return pow(a, m - 2, m)

def main():
    n, m = map(int, sys.stdin.readline().split())
    edges = [list(map(int, sys.stdin.readline().split())) for _ in range(m)]

    # Initialize the graph
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u - 1].append(v - 1)
        graph[v - 1].append(u - 1)

    # Find connected components
    visited = [False] * n
    component_sizes = []

    def dfs(node):
        stack = [node]
        size = 0
        while stack:
            u = stack.pop()
            if not visited[u]:
                visited[u] = True
                size += 1
                for v in graph[u]:
                    if not visited[v]:
                        stack.append(v)
        return size

    for i in range(n):
        if not visited[i]:
            component_sizes.append(dfs(i))

    # Calculate expected value E[X]
    expected_value = 0
    for size in component_sizes:
        expected_value += pow(2, size, MOD) * pow(2, n - size, MOD)
        expected_value %= MOD

    expected_value = (n - expected_value) % MOD

    # Calculate variance
    variance = 0
    for size in component_sizes:
        variance += pow(2, size, MOD) * pow(2, n - size, MOD)
        variance %= MOD

    variance = (n - 2 * expected_value + variance) % MOD
    variance = (variance * modinv(pow(2, n, MOD), MOD)) % MOD

    print(variance)

if __name__ == "__main__":
    main()
